(()=>{'use strict';
const SUBJECTS=[['english','英語','Aa','#845bba','單字儲備庫'],['math','數學','π','#21977b','六年級互動練兵坊'],['chinese','國語','文','#d96b45','六年級互動考卷'],['social','社會','社','#eb9a2f','六年級互動考卷'],['science','自然','科','#37a7ed','六年級互動考卷']];
const DEFAULT_UNITS={chinese:[],math:[],english:[],social:[],science:[]}; // 待正式教材/版本連接，不用模板示範課名冒充真教材
const STORAGE='berry-learning-progress-v1', REVIEW='berry-school-parent-review-v1';
const page=document.body.dataset.page==='school'?'school':'self';let month=new Date();month.setDate(1);let step=1,kind='school',subject='chinese',unitId='',customUnit='',grade='6',semester='upper',filterSubject='all';
const $=q=>document.querySelector(q),esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function safeRead(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}}
function safeWrite(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{notify('儲存失敗：請確認瀏覽器允許本機儲存');return false}}
function records(){let x=safeRead(STORAGE);return Array.isArray(x)?x.filter(v=>v&&['school','assessment'].includes(v.type)&&SUBJECTS.some(s=>s[0]===v.subjectId)&&typeof v.id==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v.date)):[]}
function visibleRecords(){return records().filter(r=>page==='school'?r.type==='school'&&String(r.grade||'6')===grade&&(r.semester||'upper')===semester:r.type==='assessment')}
function currentWeekRecords(rs){const now=new Date(),day=(now.getDay()+6)%7,start=new Date(now.getFullYear(),now.getMonth(),now.getDate()-day),end=new Date(start);end.setDate(end.getDate()+7);return rs.filter(r=>{const x=new Date(r.date+'T12:00:00');return x>=start&&x<end})}
function names(id){return SUBJECTS.find(x=>x[0]===id)||SUBJECTS[0]};function badge(id){let s=names(id);return `<span class="symbol" style="--c:${s[3]}">${s[2]}</span>`}
function nav(){return `<div class="top"><a class="brand" href="./index.html"><i aria-hidden="true">🍓</i>莓好學習區</a><nav class="tabs" aria-label="主導覽"><a href="./index.html">教材中心</a><a href="./self-progress.html" ${page==='self'?'aria-current="page"':''}>自學進度</a><a href="./school-progress.html" ${page==='school'?'aria-current="page"':''}>學校進度</a><a href="./school-progress.html#add">新增進度</a></nav><button class="secondary" id="searchHelp" aria-label="資料說明">ⓘ</button></div>`}
function bottom(){return `<nav class="bottom" aria-label="手機導覽"><a href="./index.html">⌂<br>首頁</a><a href="./index.html">▤<br>教材中心</a><button class="add" data-open aria-label="新增學習進度">+</button><a class="${page==='self'?'current':''}" href="./self-progress.html">▤<br>自學進度</a><a class="${page==='school'?'current':''}" href="./school-progress.html">▤<br>學校進度</a></nav>`}
function calendar(rs){let d=new Date(month.getFullYear(),month.getMonth(),1),offset=d.getDay(),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();const logged=new Set(rs.map(r=>r.date)),today=new Date().toLocaleDateString('sv-SE');let html='<div class="calendar">'+['日','一','二','三','四','五','六'].map(x=>`<strong class="small">${x}</strong>`).join('');for(let i=0;i<offset;i++)html+='<span></span>';for(let n=1;n<=days;n++){let key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(n).padStart(2,'0');html+=`<span class="${key===today?'active':logged.has(key)?'learned':''}" ${logged.has(key)?'title="有記錄"':''}>${n}</span>`}return html+'</div>'}
function calendarPanel(rs,school=false){return `<section class="panel"><div class="subhead"><h2>${school?'學校行事曆':'學習日曆'}</h2><div><button class="secondary" data-month="-1" aria-label="上個月">‹</button> <b id="monthLabel">${month.getFullYear()} 年 ${month.getMonth()+1} 月</b> <button class="secondary" data-month="1" aria-label="下個月">›</button></div></div>${calendar(rs)}<p class="small">粉色標記：有登記紀錄。資料只儲存在這台裝置。</p></section>`}
function selfPage(){const rr=visibleRecords(),done=rr.filter(x=>x.isCompleted),dates=new Set(rr.map(x=>x.date)),items=SUBJECTS.map(s=>{let count=rr.filter(r=>r.subjectId===s[0]).length;return `<div class="subject-row">${badge(s[0])}<div><b>${s[1]}　${esc(s[4])}</b><div class="progressbar" style="--c:${s[3]}"><span style="width:0%"></span></div><span class="small">${count} 筆手動登記｜教材總量尚未接線，完成率未計算</span></div><a class="secondary" href="./index.html">繼續學習</a></div>`}).join('');const stats=[['已學教材','—'],['完成單元',done.length],['學習時數','—'],['連續學習','—']].map(x=>`<article class="stat"><small>${x[0]}</small><b>${x[1]}</b></article>`).join('');return `<div class="hero"><h1>我的自學進度</h1><p>每天一點點，累積屬於自己的成長！<br>小小進步，都是大大的驚喜！</p><div class="art" aria-hidden="true">📊</div></div><p class="small">尚未連接各科教材進度；以下僅顯示本機手動登記，不使用模板示範數字。</p><section class="stats">${stats}</section><section class="panel subjects"><div class="subhead"><h2>各科自學進度</h2><a href="./index.html" class="small">查看教材 ›</a></div>${items}</section><div class="columns">${calendarPanel(rr)}<section class="panel"><h2>最近學習紀錄</h2>${recent(rr)}</section></div>`}
function recent(rs){return rs.length?rs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(r=>`<div class="rec">${badge(r.subjectId)}<div class="detail"><b>${esc(names(r.subjectId)[1])}　${esc(r.unitTitle)}</b><div class="small">${esc(r.date)}｜${r.type==='school'?'學校進度':'評量進度'}</div></div><span class="${r.isCompleted?'done':'pending'}">${r.isCompleted?'✓ 已完成':'未登記'}</span></div>`).join(''):'<p class="empty">目前沒有學習紀錄。可以按「新增進度」開始登記學校課程或評量。</p>'}
function filters(){return `<div class="panel filters"><label>年級<select id="grade">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${grade===String(n)?'selected':''}>${['一','二','三','四','五','六'][n-1]}年級</option>`).join('')}</select></label><label>學期<select id="semester"><option value="upper" ${semester==='upper'?'selected':''}>上學期</option><option value="lower" ${semester==='lower'?'selected':''}>下學期</option></select></label><label>科目<select id="filterSubject"><option value="all">全部科目</option>${SUBJECTS.map(s=>`<option value="${s[0]}" ${filterSubject===s[0]?'selected':''}>${s[1]}</option>`).join('')}</select></label></div>`}
function schoolPage(){let rr=currentWeekRecords(visibleRecords()),filtered=rr.filter(r=>filterSubject==='all'||r.subjectId===filterSubject),complete=rr.filter(x=>x.isCompleted),review=safeRead(REVIEW),isReviewed=review&&review.isReviewed===true;return `<div class="hero"><h1>我的學校進度</h1><p>同步學校課程，掌握學習重點！<br>跟上進度，學習更輕鬆！</p><div class="art" aria-hidden="true">🏫</div></div>${filters()}<div class="panel"><div class="subhead"><div><h2>本週完成率</h2><div class="small" id="weekStatus">已登記 ${complete.length} 筆完成紀錄，課表總數尚未接線</div></div><button class="pink" data-open>＋ 新增進度</button></div><div class="progressbar" style="--c:#ff4b7d"><span style="width:0%"></span></div><p class="small">正式課表尚未接線，不顯示虛構的 3／5 完成率。</p></div><section class="panel"><div class="subhead"><h2>本週學習記錄</h2><span class="small">共 ${rr.length} 筆</span></div><div id="schoolRecords">${recent(filtered)}</div></section><div class="columns">${calendarPanel(visibleRecords(),true)}<section class="panel review"><h2>家長本週批閱</h2><div class="reviewmark">♛ 閱</div><p class="small" id="reviewStatus">${isReviewed?'已於本機標記批閱':'尚未批閱：請家長確認本週紀錄'}</p><button class="pink" id="reviewBtn">${isReviewed?'取消本機批閱':'確認本週批閱'}</button><p class="small">目前僅有本機標記，未串接家長身分驗證，不能當作正式簽核。</p></section></div>`}
function dialog(){return `<div id="overlay" class="overlay" hidden><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><div class="subhead"><h2 id="dialogTitle">新增學習進度</h2><button class="secondary" data-close aria-label="關閉新增進度">✕</button></div><div class="steps"><span data-step="1"><i class="stepnum">1</i>選擇進度類型</span><span data-step="2"><i class="stepnum">2</i>選擇科目</span><span data-step="3"><i class="stepnum">3</i>選擇單元</span></div><div id="stepContent"></div><div class="actions"><button class="secondary" id="backBtn">上一步</button><button class="pink" id="nextBtn">下一步 ›</button></div></div></div><div class="toast" id="toast" role="status" hidden></div>`}
function notify(s){let n=$('#toast');n.textContent=s;n.hidden=false;setTimeout(()=>n.hidden=true,3600)}
function open(){step=1;kind=page==='school'?'school':'assessment';subject='chinese';unitId='';customUnit='';$('#overlay').hidden=false;document.body.style.overflow='hidden';renderStep();$('#dialogTitle').focus?.()}
function close(){$('#overlay').hidden=true;document.body.style.overflow=''}
function units(){return DEFAULT_UNITS[subject]||[]}
function renderStep(){document.querySelectorAll('[data-step]').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)===step));$('#backBtn').hidden=step===1;$('#nextBtn').textContent=step===3?'✓ 登記完成':'下一步 ›';let content='';if(step===1)content=`<p class="small">記錄完成的學校課程或評量，養成規律學習的習慣。</p><h3>① 選擇進度類型</h3><div class="options">${[['school','🏫','學校進度','記錄學校已完成的課程'],['assessment','▤','評量進度','記錄已完成的學校評量']].map(x=>`<button class="option ${kind===x[0]?'selected':''}" data-kind="${x[0]}"><span class="em">${x[1]}</span>${x[2]}<div class="small">${x[3]}</div></button>`).join('')}</div>`;if(step===2)content=`<h3>② 選擇科目（五科）</h3><div class="options five">${SUBJECTS.map(x=>`<button class="option ${subject===x[0]?'selected':''}" data-subject="${x[0]}"><span class="em">${x[2]}</span>${x[1]}</button>`).join('')}</div>`;if(step===3)content=`<h3>③ 選擇學習單元／課次</h3><p class="small">${esc(names(subject)[1])}｜${kind==='school'?'學校進度':'評量進度'}</p>${units().length?`<div class="units">${units().map(u=>`<button class="option ${unitId===u.id?'selected':''}" data-unit="${esc(u.id)}">${esc(u.unitCode)} ${esc(u.title)}</button>`).join('')}</div>`:'<p class="empty">目前尚未接上正式教材課次。可先自行輸入課次名稱，將記錄標記為「手動」，不冒充正式課本內容。</p><label for="manualUnit">手動登記課次／單元</label><input id="manualUnit" maxlength="80" placeholder="例如：第 1 課（自行輸入）" style="display:block;width:100%;padding:13px;margin-top:8px;border:1px solid #d7e0ef;border-radius:10px">'}`;$('#stepContent').innerHTML=content;$('#nextBtn').disabled=step===3&&!unitId&&!customUnit.trim();$('#nextBtn').style.opacity=$('#nextBtn').disabled?'.45':'1'}
function bind(){if(!window.__berryClickBound){window.__berryClickBound=true;document.addEventListener('click',e=>{let b=e.target.closest('[data-open],[data-close],[data-kind],[data-subject],[data-unit],[data-month]');if(!b)return;if(b.hasAttribute('data-open'))open();if(b.hasAttribute('data-close'))close();if(b.dataset.kind){kind=b.dataset.kind;renderStep()}if(b.dataset.subject){subject=b.dataset.subject;unitId='';customUnit='';renderStep()}if(b.dataset.unit){unitId=b.dataset.unit;renderStep()}if(b.dataset.month){month.setMonth(month.getMonth()+Number(b.dataset.month));render()}});}if(!window.__berryInputBound){window.__berryInputBound=true;document.addEventListener('input',e=>{if(e.target.id==='manualUnit'){customUnit=e.target.value;$('#nextBtn').disabled=!customUnit.trim();$('#nextBtn').style.opacity=customUnit.trim()?'1':'.45'}});}$('#nextBtn').onclick=()=>{if(step<3){step++;renderStep();return}let u=units().find(x=>x.id===unitId);if(!u&&!customUnit.trim())return;let rr=records();rr.push({id:'manual-'+Date.now(),type:kind,subjectId:subject,unitCode:u?u.unitCode:'自訂',unitTitle:u?u.title:customUnit.trim(),source:u?'catalog':'manual',date:new Date().toLocaleDateString('sv-SE'),grade:kind==='school'?grade:null,semester:kind==='school'?semester:null,isCompleted:true});if(safeWrite(STORAGE,rr)){close();render();notify('進度已儲存在此裝置')}};$('#backBtn').onclick=()=>{if(step>1){step--;renderStep()}};$('#overlay').onclick=e=>{if(e.target.id==='overlay')close()};if(!window.__berryKeyBound){window.__berryKeyBound=true;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#overlay').hidden)close()});}$('#searchHelp').onclick=()=>notify('本頁為獨立進度頁，尚未串接教材中心、帳號與家長認證。')}
function render(){let container=$('#app');container.innerHTML=`<main class="layout">${nav()}${page==='school'?schoolPage():selfPage()}</main>${bottom()}${dialog()}`;bind();if(window.location.hash==='#add' && $('#overlay')?.hidden){history.replaceState(null,'',window.location.pathname+window.location.search);open();}if(page==='school'){const reviewButton=$('#reviewBtn');reviewButton.onclick=()=>{let current=safeRead(REVIEW),next=!(current&&current.isReviewed===true);if(safeWrite(REVIEW,{isReviewed:next,reviewedAt:next?new Date().toISOString():null,verifiedIdentity:false}))render()};$('#filterSubject').onchange=()=>{filterSubject=$('#filterSubject').value;render()};$('#grade').onchange=()=>{grade=$('#grade').value;render()};$('#semester').onchange=()=>{semester=$('#semester').value;render()};}}
render();})();
